#![allow(clippy::unnecessary_cast)] // generated by swift-bridge's init shim.

//! the swift-bridge interface the apple apps link against. swift-bridge-build
//! reads this file to generate the swift glue, so the bridge itself stays
//! exactly as the swift side expects it.

use crate::{SpotifyCore, core_version, equalizer_frequencies};

#[swift_bridge::bridge]
mod ffi {
    extern "Rust" {
        type SpotifyCore;

        #[swift_bridge(init)]
        fn new() -> SpotifyCore;

        async fn connect(&self, access_token: String, client_id: String) -> Result<(), String>;
        fn disconnect(&self);

        async fn play_track(&self, spotify_uri: String) -> Result<(), String>;

        fn load_track(&self, spotify_uri: String) -> Result<(), String>;

        fn play(&self) -> Result<(), String>;
        fn pause(&self) -> Result<(), String>;
        fn session_is_valid(&self) -> bool;
        fn audio_output_stalled(&self) -> bool;

        fn set_equalizer(&self, gains_db: Vec<f32>) -> Result<(), String>;
        fn set_playback_shaping(
            &self,
            tempo: f32,
            pitch_semitones: f32,
            preserves_pitch: bool,
        ) -> Result<(), String>;
        fn equalizer_frequencies() -> Vec<f32>;
        async fn restart_audio_output(&self) -> Result<(), String>;
        fn seek(&self, position_ms: u32) -> Result<(), String>;
        fn playback_position_ms(&self) -> u32;
        fn playback_duration_ms(&self) -> u32;
        fn take_end_of_track(&self) -> bool;

        fn set_stream_quality(&self, kbps: u32) -> Result<(), String>;

        fn set_volume(&self, volume: f32) -> Result<(), String>;
        fn volume(&self) -> f32;
        async fn lyrics_json(&self, spotify_uri: String) -> Result<String, String>;
        fn set_spectrum_enabled(&self, enabled: bool);
        fn spectrum_levels(&self) -> Vec<f32>;
        fn core_version() -> String;
    }
}
